#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// 2D fields: i x j, with j the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec);
	// 1D fictitious array over time
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);
} tuning;

// Array initialization
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Initialize fict[t] = t
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = (num_t)t;
	});

	// Dimensions (spatial)
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Initialize ex, ey, hz over the spatial grid.
	// Traversal order is i (outer) x j (inner); j is contiguous in memory.
	traverser(ex, ey, hz).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		ex[state] = ((num_t)i * (j + 1)) / (num_t)nx;
		ey[state] = ((num_t)i * (j + 2)) / (num_t)ny;
		hz[state] = ((num_t)i * (j + 3)) / (num_t)nx;
	});
}

// Main computational kernel
// - outer loop over time t
// - three spatial update sweeps for ey, ex and hz
//
// Optimizations over the baseline version:
//  * Time dimension is handled by a dedicated traverser over `fict` only.
//    The spatial sweeps then work purely on (i,j) states, avoiding an
//    unused 't' index for ex/ey/hz accesses.
//  * A single spatial traverser `space_trav` is reused for all three
//    sweeps in a given call.
//  * Repeated bag lookups at the same state are factored into locals
//    (helps the compiler generate less address arithmetic).
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Spatial sizes
	const std::size_t nx = ex | get_length<'i'>();
	const std::size_t ny = ex | get_length<'j'>();

	// Constants in the right scalar type
	const num_t half  = SCALAR_VAL(0.5);
	const num_t c07   = SCALAR_VAL(0.7);

	// Spatial traverser (i x j) reused inside each time step
	auto space_trav = traverser(ex, ey, hz);

#pragma scop
	// Outer time loop over t
	traverser(fict).for_each([&](auto t_state) {
		// Current time slice value: fict[t]
		const num_t fict_t = fict[t_state];

		// ------------------------------------------------------------------
		// 1) Boundary condition:
		//    ey[0][j] = fict[t] for all j
		// ------------------------------------------------------------------
		space_trav
			// fix i = 0, iterate all j
			.order(noarr::fix<'i'>(0))
			.for_each([&](auto state) {
				// state has i = 0, all j
				ey[state] = fict_t;
			});

		// ------------------------------------------------------------------
		// 2) Update ey in the interior:
		//    ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j])
		//    for i = 1..nx-1, j = 0..ny-1
		// ------------------------------------------------------------------
		space_trav
			// restrict i to [1, nx-1] (length nx-1 starting at 1)
			.order(noarr::slice<'i'>(1, nx - 1))
			.for_each([&](auto state) {
				// state: i in [1, nx-1], j in [0, ny-1]
				auto state_im1j = state - noarr::idx<'i'>(1);

				const num_t hz_ij   = hz[state];
				const num_t hz_im1j = hz[state_im1j];

				ey[state] = ey[state] - half * (hz_ij - hz_im1j);
			});

		// ------------------------------------------------------------------
		// 3) Update ex in the interior:
		//    ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1])
		//    for i = 0..nx-1, j = 1..ny-1
		// ------------------------------------------------------------------
		space_trav
			// restrict j to [1, ny-1] (length ny-1 starting at 1)
			.order(noarr::slice<'j'>(1, ny - 1))
			.for_each([&](auto state) {
				// state: i in [0, nx-1], j in [1, ny-1]
				auto state_ijm1 = state - noarr::idx<'j'>(1);

				const num_t hz_ij   = hz[state];
				const num_t hz_ijm1 = hz[state_ijm1];

				ex[state] = ex[state] - half * (hz_ij - hz_ijm1);
			});

		// ------------------------------------------------------------------
		// 4) Update hz in the interior:
		//    hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j]
		//                       + ey[i+1][j] - ey[i][j])
		//    for i = 0..nx-2, j = 0..ny-2
		// ------------------------------------------------------------------
		space_trav
			// keep i in [0, nx-2], j in [0, ny-2]
			.order(noarr::slice<'i'>(0, nx - 1) ^ noarr::slice<'j'>(0, ny - 1))
			.for_each([&](auto state) {
				// state: i in [0, nx-2], j in [0, ny-2]
				auto state_i_jp1 = state + noarr::idx<'j'>(1);
				auto state_ip1_j = state + noarr::idx<'i'>(1);

				// Load all values we need into locals to keep address
				// calculations to a minimum and enable better reuse.
				const num_t hz_ij    = hz[state];
				const num_t ex_ij    = ex[state];
				const num_t ex_i_jp1 = ex[state_i_jp1];
				const num_t ey_ij    = ey[state];
				const num_t ey_ip1_j = ey[state_ip1_j];

				const num_t curl_ex = ex_i_jp1 - ex_ij;
				const num_t curl_ey = ey_ip1_j - ey_ij;

				hz[state] = hz_ij - c07 * (curl_ex + curl_ey);
			});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t tmax = TMAX;
	std::size_t nx = NX;
	std::size_t ny = NY;

	// Set lengths for spatial and temporal dimensions
	auto set_space = noarr::set_length<'i'>(nx) ^ noarr::set_length<'j'>(ny);
	auto set_time  = noarr::set_length<'t'>(tmax);

	// Allocate bags
	auto ex = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto ey = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto hz = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto fict = noarr::bag(noarr::scalar<num_t>() ^ tuning.fict_layout ^ set_time);

	// Initialize arrays
	init_array(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_fdtd_2d(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print results (if requested, mimicking PolyBench's conditional printing)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);

		// Hoist 'i' so each row is contiguous in the serialized output
		noarr::serialize_data(std::cerr, ex.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, ey.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, hz.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print elapsed time (seconds)
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
