// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// 2D fields: i x j, with j the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec);
	// 1D fictitious array over time
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);
} tuning;

// Array initialization
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Hoist reciprocals: avoid repeated divisions inside the hot loops
	const num_t inv_nx = num_t(1.0) / num_t(nx);
	const num_t inv_ny = num_t(1.0) / num_t(ny);

	// Initialize fict[t] = t
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = num_t(t);
	});

	// Initialize ex, ey, hz on the 2D grid
	traverser(ex, ey, hz).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		const num_t ni = num_t(i);
		const num_t nj1 = num_t(j + 1);
		const num_t nj2 = num_t(j + 2);
		const num_t nj3 = num_t(j + 3);

		// Original formulas:
		// ex[i][j] = (i * (j + 1)) / nx;
		// ey[i][j] = (i * (j + 2)) / ny;
		// hz[i][j] = (i * (j + 3)) / nx;
		//
		// Here written with precomputed reciprocals to reduce divisions.
		ex[state] = ni * nj1 * inv_nx;
		ey[state] = ni * nj2 * inv_ny;
		hz[state] = ni * nj3 * inv_nx;
	});
}

// Main computational kernel
//
// Semantics follow the PolyBench fdtd-2d kernel:
//
// for t = 0..tmax-1
//   for j = 0..ny-1
//     ey[0][j] = fict[t];
//   for i = 1..nx-1
//     for j = 0..ny-1
//       ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);
//   for i = 0..nx-1
//     for j = 1..ny-1
//       ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);
//   for i = 0..nx-2
//     for j = 0..ny-2
//       hz[i][j] -= 0.7 * ( (ex[i][j+1]-ex[i][j]) + (ey[i+1][j]-ey[i][j]) );
//
// The implementation below keeps this structure but expresses all loop nests
// using Noarr traversers. Spatial loops are organized as i-major / j-minor,
// with j contiguous in memory as prescribed by tuning.field_layout.
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Numerical coefficients, hoisted once
	const num_t half = SCALAR_VAL(0.5);
	const num_t seven_tenths = SCALAR_VAL(0.7);

#pragma scop
	// Outer time loop over t: traverser over fict (1D in 't')
	traverser(fict).for_each([=](auto t_state) {
		// Current time index is get_index<'t'>(t_state), but the only value
		// we need repeatedly is fict[t]. Hoist it to a scalar to avoid
		// redundant memory accesses inside the boundary loop.
		const num_t fict_t = fict[t_state];

		// --------------------------------------------------------------------
		// 1) ey[0][j] = fict[t] for all j = 0..ny-1
		//    (update single boundary row i = 0)
		// --------------------------------------------------------------------
		traverser(ey)
			.order(noarr::fix<'i'>(0))
			.for_each([=](auto state) {
				// state: i = 0, j in [0, ny-1]
				ey[state] = fict_t;
			});

		// --------------------------------------------------------------------
		// 2) ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j])
		//    for i = 1..nx-1, j = 0..ny-1
		// --------------------------------------------------------------------
		traverser(ey, hz)
			// slice<'i'>(start, length) keeps indices i in [start, start+length-1]
			// Here: i in [1, nx-1]; length = nx-1.
			.order(noarr::slice<'i'>(1, nx - 1))
			.for_each([=](auto state) {
				// state: i in [1, nx-1], j in [0, ny-1]
				auto state_im1j = state - noarr::idx<'i'>(1); // (i-1, j)

				ey[state] = ey[state]
				            - half * (hz[state] - hz[state_im1j]);
			});

		// --------------------------------------------------------------------
		// 3) ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1])
		//    for i = 0..nx-1, j = 1..ny-1
		// --------------------------------------------------------------------
		traverser(ex, hz)
			// j in [1, ny-1]; length = ny-1.
			.order(noarr::slice<'j'>(1, ny - 1))
			.for_each([=](auto state) {
				// state: i in [0, nx-1], j in [1, ny-1]
				auto state_ijm1 = state - noarr::idx<'j'>(1); // (i, j-1)

				ex[state] = ex[state]
				            - half * (hz[state] - hz[state_ijm1]);
			});

		// --------------------------------------------------------------------
		// 4) hz[i][j] -= 0.7 * ( ex[i][j+1] - ex[i][j]
		//                       + ey[i+1][j] - ey[i][j])
		//    for i = 0..nx-2, j = 0..ny-2
		// --------------------------------------------------------------------
		traverser(ex, ey, hz)
			// i in [0, nx-2], j in [0, ny-2]:
			// slice<'i'>(0, nx-1) keeps i = 0..nx-2
			// slice<'j'>(0, ny-1) keeps j = 0..ny-2
			.order(noarr::slice<'i'>(0, nx - 1) ^ noarr::slice<'j'>(0, ny - 1))
			.for_each([=](auto state) {
				// state: i in [0, nx-2], j in [0, ny-2]
				auto state_i_jp1 = state + noarr::idx<'j'>(1); // (i, j+1)
				auto state_ip1_j = state + noarr::idx<'i'>(1); // (i+1, j)

				hz[state] = hz[state]
				            - seven_tenths * (
