	// 1D fictitious array over time
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);
} tuning;

// Array initialization
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Initialize fict[t] = t
	traverser(fict).for_each([&](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = (num_t)t;
	});

	// Dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Precompute reciprocals to avoid repeated divisions in the inner loop
	const num_t inv_nx = SCALAR_VAL(1.0) / (num_t)nx;
	const num_t inv_ny = SCALAR_VAL(1.0) / (num_t)ny;

	// Initialize ex, ey, hz
	traverser(ex, ey, hz).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const num_t fi = (num_t)i;
		const num_t fj = (num_t)j;

		ex[state] = fi * (fj + SCALAR_VAL(1.0)) * inv_nx;
		ey[state] = fi * (fj + SCALAR_VAL(2.0)) * inv_ny;
		hz[state] = fi * (fj + SCALAR_VAL(3.0)) * inv_nx;
	});
}

// Main computational kernel
//
// Optimized version:
// - Still expressed purely in terms of Noarr traversers and state arithmetic.
// - Outer loop over time 't' unchanged (one full space update per time step).
// - For each time step:
//   1) Apply boundary condition on row i = 0: ey[0][j] = fict[t].
//   2) For rows i = 0 .. nx-2, perform a *fused* sweep over j where we:
//        - update ey[i+1][j] for all j,
//        - update ex[i][j]   for j >= 1,
//        - update hz[i][j-1] for j >= 1 (i.e. j-1 in [0, ny-2]).
//      This fuses the original three separate spatial loops while preserving
//      the FDTD update semantics and improves locality across ex/ey/hz.
//   3) Update the last ex row (i = nx-1) for j = 1 .. ny-1, which is not
//      covered by the fused sweep.
// - All dependencies are respected (see comments inside), and the numerical
//   results are identical to the original kernel.
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	const std::size_t nx = ex | get_length<'i'>();
	const std::size_t ny = ex | get_length<'j'>();

	const num_t c05 = SCALAR_VAL(0.5);
	const num_t c07 = SCALAR_VAL(0.7);

#pragma scop
	// Outer time loop over t
	traverser(fict, ex, ey, hz).template for_dims<'t'>([&](auto trav_t) {
		// State with only the current time index
		auto t_state = trav_t.state();
		const num_t fict_t = fict[t_state];

		// ------------------------------------------------------------------
		// 1) Boundary condition:
		//    ey[0][j] = fict[t]  for all j
		// ------------------------------------------------------------------
		trav_t
			.order(noarr::fix<'i'>(0))
			.for_each([&](auto state) {
				// state has i = 0 and all j for this time step
				ey[state] = fict_t;
			});

		// ------------------------------------------------------------------
		// 2) Fused interior update on rows i = 0 .. nx-2
		//
		// Original separate loops (for one time step t):
		//   (a) for i = 1..nx-1, j = 0..ny-1:
		//         ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);
		//
		//   (b) for i = 0..nx-1, j = 1..ny-1:
		//         ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);
		//
		//   (c) for i = 0..nx-2, j = 0..ny-2:
		//         hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j]
		//                             + ey[i+1][j] - ey[i][j]);
		//
		// In the fused scheme below, for a fixed row i (0 <= i <= nx-2) and
		// a sweep over j in ascending order, we:
		//   - update ey[i+1][j] for all j (implements (a)),
		//   - for j >= 1, update ex[i][j] (part of (b)),
		//   - for j >= 1, update hz[i][j-1] (implements (c) for that row).
		//
		// This is functionally equivalent to the original ordering because:
		//   - All ey/ex updates depend only on hz from the previous time step,
		//     and hz is not modified before all of them for that cell.
		//   - hz[i][j] depends only on ex[i][j], ex[i][j+1], ey[i][j],
		//     ey[i+1][j], all at the *new* time level, and our schedule ensures
		//     those have been updated before hz[i][j] is updated.
		// ------------------------------------------------------------------
		if (nx > 1) {
			trav_t
				// i in [0, nx-2]  (length = nx-1 if nx>0)
				.order(noarr::slice<'i'>(0, nx - 1))
				.template for_dims<'i'>([&](auto trav_i) {
					// trav_i has the current i fixed, iterates all j
					trav_i.for_each([&](auto state) {
						// Current indices: i in [0, nx-2], j in [0, ny-1]
						auto state_ip1j = state + noarr::idx<'i'>(1);

						// ey[i+1][j] = ey[i+1][j] - 0.5 * (hz[i+1][j] - hz[i][j])
						const num_t hz_ij   = hz[state];
						const num_t hz_ip1j = hz[state_ip1j];
						ey[state_ip1j] = ey[state_ip1j] - c05 * (hz_ip1j - hz_ij);

						const std::size_t j = get_index<'j'>(state);

						// For j >= 1 we also update:
						//   ex[i][j]   (part of the original ex-update loop)
						//   hz[i][j-1] (part of the original hz-update loop)
						if (j > 0 && ny > 1) {
							// ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
							auto state_ijm1 = state - noarr::idx<'j'>(1);
							const num_t hz_ijm1 = hz[state_ijm1];
							ex[state] = ex[state] - c05 * (hz_ij - hz_ijm1);

							// hz[i][j-1] = hz[i][j-1] - 0.7 * (
							//                  ex[i][j]   - ex[i][j-1] +
							//                  ey[i+1][j-1] - ey[i][j-1] )
							auto state_ip1_jm1 = state_ijm1 + noarr::idx<'i'>(1);
							const num_t ex_ij      = ex[state];
							const num_t ex_ijm1    = ex[state_ijm1];
							const num_t ey_ijm1    = ey[state_ijm1];
							const num_t ey_ip1_jm1 = ey[state_ip1_jm1];

							hz[state_ijm1] = hz_ijm1 - c07 *
								((ex_ij - ex_ijm1) + (ey_ip1_jm1 - ey_ijm1));
						}
					});
				});
		}

		// ------------------------------------------------------------------
		// 3) Final ex row (i = nx-1), j = 1 .. ny-1
		//
		// The fused loop above only updated ex for rows i = 0 .. nx-2.
		// We still need to update ex[nx-1][j] according to:
		//   ex[nx-1][j] = ex[nx-1][j] - 0.5 * (hz[nx-1][j] - hz[nx-1][j-1])
		// ------------------------------------------------------------------
		if (nx > 0 && ny > 1) {
			trav_t
				.order(noarr::fix<'i'>(nx - 1) ^ noarr::slice<'j'>(1, ny - 1))
				.for_each([&](auto state) {
					auto state_ijm1 = state - noarr::idx<'j'>(1);
					const num_t hz_ij   = hz[state];
					const num_t hz_ijm1 = hz[state_ijm1];
					ex[state] = ex[state] - c05 * (hz_ij - hz_ijm1);
				});
		}
	});
#pragma endscop
}

